/* style.css — classes emitted by sb-waybar-status.sh */
#custom-soundboard {
  font-family: "JetBrainsMono Nerd Font", monospace;
  font-size: 15px;
  padding: 0 12px;
  color: #8FECD5;
}
#custom-soundboard:hover { background: rgba(173, 240, 233, 0.10); }
#custom-soundboard.inactive { color: #5b5b5b; }
#custom-soundboard.armed { color: #8FECD5; }
#custom-soundboard.engaged { color: #ADF0E9; background: rgba(173, 240, 233, 0.16); }
